package medium;public class InsertDeleteGetRandomO1{java.util.Map<Integer,Integer>m=new java.util.HashMap<>();java.util.List<Integer>l=new java.util.ArrayList<>();void insert(int v){if(!m.containsKey(v)){m.put(v,l.size());l.add(v);}}boolean remove(int v){if(!m.containsKey(v))return false;int i=m.get(v),last=l.get(l.size()-1);m.put(last,i);l.set(i,last);l.remove(l.size()-1);m.remove(v);return true;}int getRandom(){return l.get((int)(Math.random()*l.size()));}public static void main(String[]args){System.out.println("Random O(1) works\n");}}
